<div class="card"><h2>Google Drive</h2><?php foreach($drives as $d):?><p><?=e($d['account_email']??'Google Drive')?> — <span class="badge"><?=e($d['status'])?></span></p><?php endforeach;?><a class="btn primary" href="<?=e(base_url('oauth/google.php?provider=drive'))?>">Connect / Reconnect Drive</a></div>
<div class="card"><h2>Map Drive folder to channel</h2><p class="muted">Paste the Google Drive folder ID. The bot validates that it is a real folder before saving.</p><form method="post" class="grid formgrid"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="save"><label>Drive connection<select name="drive_connection_id" required><?php foreach($drives as $d):?><option value="<?=e((string)$d['id'])?>"><?=e($d['account_email']?:'Drive #'.$d['id'])?> — <?=e($d['status'])?></option><?php endforeach;?></select></label><label>YouTube channel<select name="youtube_channel_id" required><?php foreach($channels as $c):?><option value="<?=e((string)$c['id'])?>"><?=e($c['channel_name'])?></option><?php endforeach;?></select></label><label>Folder ID<input name="folder_id" required placeholder="1AbCdEf..." autocomplete="off"></label><label>Folder name (optional)<input name="folder_name" placeholder="Auto-detected if blank"></label><button class="btn primary">Validate & Add Mapping</button></form></div>
<div class="card"><h2>Mappings</h2><table><tr><th>Folder</th><th>Channel</th><th>Drive account</th><th>Last scan</th><th></th></tr><?php foreach($folders as $f):?><tr><td><?=e($f['folder_name'])?><div class="muted"><?=e($f['folder_id'])?></div></td><td><?=e($f['channel_name'])?></td><td><?=e($f['account_email']??'')?></td><td><?=e($f['last_scanned_at']??'Never')?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e((string)$f['id'])?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div>
